create database customer_behavior;
use customer_behavior;

SELECT * FROM customer;

-- 1. What is the total revenue generated by male vs. female customers?
select gender, 
       sum(purchase_amount) as revenue
from customer
group by gender;

-- 2. Which customers used a discount but still spent more than the average purchase amount? 
select customer_id, purchase_amount 
from customer 
where discount_applied = 'Yes' and purchase_amount > (
select avg(purchase_amount) 
from customer);

-- 3. Which are the top 5 products with the highest average review rating?
select item_purchased, 
       round(avg(review_rating),2) as "Average Product Rating"
from customer
group by item_purchased
order by avg(review_rating) desc
limit 5;

-- 4. Compare the average Purchase Amounts between Standard and Express Shipping. 
select shipping_type, 
	   round(AVG(purchase_amount),2) as avg_purchase
from customer
where shipping_type in ('Standard','Express')
group by shipping_type;

-- 5. Do subscribed customers spend more? Compare average spend and total revenue 
-- between subscribers and non-subscribers.
select subscription_status,
       count(customer_id) as total_customers,
       round(AVG(purchase_amount),2) as avg_spend,
       round(sum(purchase_amount),2) as total_revenue
from customer
group by subscription_status
order by total_revenue desc;

-- 6. Which 5 products have the highest percentage of purchases with discounts applied?
select item_purchased, 
       round(100.0 * sum(case when discount_applied = 'Yes' then 1 else 0 end)/COUNT(*),2) as discount_rate
from customer
group by item_purchased
order by discount_rate desc
limit 5;

-- 7. Segment customers into New, Returning, and Loyal based on their total 
-- number of previous purchases, and show the count of each segment. 
with customer_type as (
select customer_id, previous_purchases,
case 
    when previous_purchases <= 5 then 'New'
    when previous_purchases between 6 and 15 then 'Returning'
    else 'Loyal'
    end as customer_segment
from customer)

select customer_segment,count(*) as "Number of Customers" 
from customer_type 
group by customer_segment;

-- 8. What are the top 3 most purchased products within each category? 
with item_counts as (
    select category,
           item_purchased,
           count(customer_id) as total_orders,
           dense_rank() over (partition by category order by COUNT(customer_id) desc) as item_rank
    from customer
    group by category, item_purchased
)
select item_rank,category, item_purchased, total_orders
from item_counts
where item_rank <=3;
 
-- 9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select case when previous_purchases > 5 then 'Repeat' else 'Non-repeat' end as buyer_type,
       COUNT(*) as customers,
       ROUND(100.0 * SUM(subscription_status = 'Yes') / COUNT(*), 1) as subscription_rate
from customer
group by buyer_type;

-- 10. What is the revenue contribution of each age group? 
select age_group,
    sum(purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue desc;

-- 11. Revenue and average spend by category and season
select category, season,
       sum(purchase_amount) as revenue,
       round(avg(purchase_amount), 2) as avg_spend
from customer
group by category, season
order by category, revenue desc;

-- 12. Top 10 states by orders and revenue
select location,
       count(*) as orders,
       sum(purchase_amount) as revenue
from customer
group by location
order by revenue desc
limit 10;

-- 13. Payment method breakdown
select payment_method,
       count(*) as orders,
       sum(purchase_amount) as revenue,
       round(avg(purchase_amount), 2) as avg_spend
from customer
group by payment_method
order by revenue desc;
